      "definitions": [
        {
          "term": "Physics",
          "def": "The branch of science that involves the study of physical universe: energy, matter, and how they are related."
        },
        {
          "term": "Physical Quantity",
          "def": "A quantity that can be measured; e.g. length, mass, time, temperature."
        },
        {
          "term": "Base Quantities",
          "def": "The minimum number of physical quantities selected and standardized such that all other quantities can be expressed in terms of these."
        },
        {
          "term": "Derived Quantities",
          "def": "Physical quantities defined in terms of base quantities. E.g. area = length², velocity = length/time."
        },
        {
          "term": "SI Units",
          "def": "International System of Units — a complete set of units based on seven base units, abbreviated as SI from French 'Système International'."
        },
        {
          "term": "Scientific Notation",
          "def": "An internationally accepted way of writing numbers as M × 10ⁿ where 1 ≤ M < 10."
        },
        {
          "term": "Least Count",
          "def": "The minimum value that can be measured on the scale of a measuring instrument."
        },
        {
          "term": "Vernier Callipers",
          "def": "A device used to measure a fraction of the smallest scale division by sliding another scale over it; accurate to 0.1 mm."
        },
        {
          "term": "Screw Gauge",
          "def": "A device used to measure a fraction of the smallest scale division by rotatory motion of circular scale over it; accurate to 0.01 mm."
        },
        {
          "term": "Significant Figures",
          "def": "The accurately known digits and the first doubtful digit in any measurement."
        },
        {
          "term": "Measurement",
          "def": "Comparison between an unknown quantity and a standard to see how many times as big it is."
        },
        {
          "term": "Pitch (Screw Gauge)",
          "def": "The distance traveled by the circular scale on the linear scale in one complete rotation of the screw gauge."
        }
      ],
