          {
            "q": "Derive the formula for kinetic energy using Newton's equations of motion.",
            "ans": "Consider a body of mass m starting from rest (vi = 0) and accelerating uniformly. From third equation of motion: 2as = vf² − vi² = vf² − 0 = vf². Multiply both sides by m/2: (m/2)×2as = (m/2)×vf². Therefore: mas = ½mv². Since F = ma (Newton's 2nd law): Fs = ½mv². Work done = Fs = W. Therefore: W = ½mv² = Kinetic Energy. EK = ½mv²."
          },
          {
            "q": "State and explain law of conservation of energy with example of a falling body.",
            "ans": "Law: Total energy of an isolated system is constant — energy can be transformed but not created or destroyed. Example (Falling ball from height h): At top: v = 0, KE = 0, PE = mgh. Total energy = mgh. During fall (at height y): v² = 2g(h−y), KE = ½mv² = mg(h−y), PE = mgy. Total = mg(h−y) + mgy = mgh (constant!). At bottom: v² = 2gh, KE = mgh, PE = 0. Total = mgh (constant!). This shows energy is conserved throughout."
          }
