          {
            "q": "Explain the characteristics of sound (Loudness, Pitch, and Quality) in detail, specifying the physical factors on which each depends.",
            "ans": "1. Loudness:\n- Definition: The auditory sensation by which the ear perceives a sound as faint or loud.\n- Physical Factors:\n  * Amplitude of vibration: Loudness is directly related to amplitude (Intensity I ∝ A²). Greater amplitude creates larger pressure variations in air, producing a louder sensation.\n  * Surface area of vibrating body: A larger vibrating area displaces more air molecules per cycle. For instance, a bass drum produces a much louder sound than a tuning fork.\n  * Distance from source: Sound intensity decreases inversely with the square of distance (I ∝ 1/r²), so sound becomes fainter as distance increases.\n\n2. Pitch:\n- Definition: The characteristic of sound by which a shrill sound can be distinguished from a grave (flat) sound.\n- Physical Factor:\n  * Frequency: Pitch depends directly on frequency. High-frequency vibrations (e.g. 1000 Hz) produce a shrill, high-pitched note (like a whistle or child's voice), while low-frequency vibrations (e.g. 100 Hz) produce a grave, low-pitched note (like a bass drum or thunder).\n\n3. Quality (Timbre):\n- Definition: The characteristic of sound that allows a listener to distinguish between two notes of identical pitch and loudness produced by different musical instruments.\n- Physical Factor:\n  * Waveform and Harmonics: Every musical instrument produces a fundamental frequency along with a unique blend of overtones (harmonics). The resultant complex waveform is distinctive; for example, a piano and a violin sounding middle C (256 Hz) have the same pitch and loudness but distinct, recognizable tonal quality."
          },
          {
            "q": "What is an echo? Derive the mathematical condition for hearing a distinct echo, and explain how the echo principle is used in SONAR.",
            "ans": "1. Definition of Echo:\n- An echo is the repetition of sound caused by the reflection of sound waves from a distant obstacle back to the listener.\n\n2. Mathematical Condition:\n- The human ear and brain possess auditory persistence: a sensation of sound lingers in consciousness for about 0.1 second (t = 0.1 s).\n- To hear a clear, distinct echo, the reflected sound wave must reach the ear at least 0.1 s after the original sound.\n- Distance traveled by sound: 2s = v * t => s = (v * t) / 2.\n- At 20°C in air, speed of sound v ≈ 343 m/s:\n  s = (343 m/s * 0.1 s) / 2 = 34.3 / 2 = 17.15 m ≈ 17.2 m.\n- Therefore, the reflecting barrier must be located at a minimum distance of 17.2 meters from the source.\n\n3. Application in SONAR:\n- SONAR (Sound Navigation and Ranging) utilizes high-frequency ultrasound pulses sent downward from a ship's transducer into the ocean.\n- The pulse reflects off the ocean floor (or submerged submarine) and is detected by a hydrophone receiver.\n- The total travel time t is recorded electronically. Knowing the speed of sound in seawater (v ≈ 1530 m/s), depth d is calculated using:\n  d = (v * t) / 2."
          }
