            "ans": "1. Construction:\n- A compound microscope consists of two converging convex lenses mounted coaxially in a metal tube:\n  * Objective Lens: Located near the specimen; has a very short focal length f_o and a small aperture to gather intense light.\n  * Eyepiece (Ocular Lens): Located near the observer's eye; has a comparatively larger focal length f_e and larger aperture.\n\n2. Working and Image Formation:\n- The specimen AB is placed on a glass slide just outside the principal focus of the objective lens (p_o slightly greater than f_o).\n- The objective lens forms a real, inverted, and magnified intermediate image A'B' inside the focal length of the eyepiece (inside f_e).\n- The eyepiece acts as a magnifying glass (simple microscope), viewing intermediate image A'B' and producing a final virtual, highly magnified, inverted image A''B'' at the least distance of distinct vision (D = 25 cm).\n\n3. Magnifying Power Formula:\n- Total magnification M is the product of the linear magnification of the objective (m_o) and the angular magnification of the eyepiece (m_e):\n  M = m_o * m_e\n- For the objective: m_o = q_o / p_o ≈ L / f_o (where L is the tube length between lenses).\n- For the eyepiece acting as a simple magnifier: m_e = 1 + D / f_e ≈ D / f_e.\n- Therefore: M = (L / f_o) * (D / f_e)."
