            "ans": "1. Statement: The electrostatic force of attraction or repulsion between two stationary point charges is directly proportional to the product of the magnitudes of the charges and inversely proportional to the square of the distance between them.\n2. Mathematical Form: F = k * (|q1 * q2|) / r^2, where k = 1 / (4 * pi * epsilon_0) ≈ 9 x 10^9 N*m^2/C^2 in vacuum.\n3. Factors affecting force:\n- Magnitude of charges: F ∝ q1 * q2 (greater charges produce stronger force).\n- Distance: F ∝ 1/r^2 (inverse square law; doubling distance reduces force to 1/4th).\n- Medium: In the presence of an insulator/dielectric of relative permittivity epsilon_r, the force is reduced by a factor epsilon_r: F_med = F_vac / epsilon_r."
