        "lq": [
          {
            "q": "Describe the five main components of an Information and Communication Technology (ICT) system and explain the flow of information through a communication network.",
            "ans": "1. Five Components of ICT:\n- Hardware: Physical electronic machinery such as central processing units (CPUs), memory chips, monitors, cables, and routers.\n- Software: System software (operating systems) and application software (word processors, browsers) that provide operating instructions.\n- Data/Information: Raw facts and figures entered into the system that are processed into useful, meaningful information.\n- Procedures: Set of rules, protocols, and security guidelines governing system usage and data processing.\n- People: Computer users, system administrators, software developers, and maintenance engineers.\n\n2. Flow of Information:\n- Information Source: Originates the message.\n- Transmitter: Converts the message into electrical or optical signals suitable for transmission (e.g., microphone, video camera).\n- Transmission Channel: The physical medium carrying the signal (twisted-pair wire, coaxial cable, free space via radio waves, or optical fiber via light).\n- Receiver: Intercepts the signal and reconstructs the original message (e.g., radio tuner, loudspeaker, monitor).\n- Destination: The person or device receiving the information."
          },
          {
            "q": "Explain the construction and working of optical fibers. State their key advantages over traditional copper cables in telecommunications.",
            "ans": "1. Construction: An optical fiber consists of three concentric layers:\n- Core: Central thin cylinder of ultra-pure silica glass with high refractive index (n1 ≈ 1.52).\n- Cladding: Surrounding glass layer with a lower refractive index (n2 ≈ 1.48).\n- Protective Jacket: Outer plastic coating providing mechanical strength and moisture protection.\n\n2. Working Principle: Operates on Total Internal Reflection. When light is launched into the core at an angle greater than the critical angle (sin θc = n2 / n1), it cannot escape into the cladding. Instead, it reflects completely back into the core and propagates down the fiber.\n\n3. Advantages over Copper Cables:\n- Immense Bandwidth: Optical fibers can carry thousands of gigabits per second simultaneously using different wavelengths of light (WDM).\n- Low Attenuation: Signals travel tens of kilometers without requiring repeaters or amplifiers.\n- Immunity to Electromagnetic Interference (EMI): Light signals are unaffected by lightning, power lines, or radio interference.\n- Security: Difficult to tap without detecting signal leakage.\n- Lightweight and Compact: Vastly thinner and lighter than bulky copper cables."
          },
          {
            "q": "Discuss the major applications of the internet in society today. What are the associated risks and what precautions should be taken to ensure cybersecurity?",
            "ans": "1. Major Applications of Internet:\n- Global Communication: Instant email, messaging, voice-over-IP (VoIP), and video conferencing.\n- Education: Online encyclopedias, digital libraries, interactive distance learning, and virtual classrooms.\n- E-Commerce & Banking: Online shopping, electronic bill payments, and digital money transfers.\n- Healthcare: Telemedicine, remote specialist consultations, and electronic patient medical records.\n\n2. Associated Risks:\n- Malware & Viruses: Programs that damage files, corrupt operating systems, or lock data (ransomware).\n- Cybercrime & Identity Theft: Phishing and hacking to steal personal credentials, passwords, and credit card information.\n- Cyberbullying & Misinformation: Online harassment and rapid spread of fake news on social media.\n- Loss of Privacy: Tracking of personal browsing habits and data profiling.\n\n3. Precautionary & Cybersecurity Measures:\n- Use strong, unique passwords with two-factor authentication (2FA).\n- Install and regularly update licensed antivirus software and firewall protection.\n- Avoid opening suspicious email attachments or clicking unknown web links.\n- Perform regular off-site backups of critical data.\n- Limit sharing of sensitive personal information on public social platforms."
          }
        ]
